def split_by_percent(cents: int, percent_specs: list[str]) -> dict[str, int]:
    """Split by "NAME=PCT" specs whose whole-number percentages add up to 100."""
    parsed = [_parse_percent_spec(spec) for spec in percent_specs]
    people = [name for name, _ in parsed]
    percents = [percent for _, percent in parsed]
    _reject_duplicates(people)
    if sum(percents) != FULL_PERCENT:
        raise MoneyError(f"percentages must add up to {FULL_PERCENT}, got {sum(percents)}")
    return dict(zip(people, allocate(cents, percents)))


