    duplicates = sorted({name for name in people if people.count(name) > 1})
    if duplicates:
        raise MoneyError(f"listed more than once: {', '.join(duplicates)}")


def _parse_percent_spec(spec: str) -> tuple[str, int]:
    name, separator, text = spec.partition("=")
    name = name.strip()
    text = text.strip()
    if not separator or not name or not (text.isascii() and text.isdigit()):
        raise MoneyError(f"expected NAME=PCT with a whole number percentage: {spec!r}")
    return name, int(text)

