def test_percent_split_is_recorded(run):
    run(
        "add", "--paid-by", "alice", "--amount", "10.00", "--description", "Dinner",
        "--percent", "alice=50", "--percent", "bob=30", "--percent", "carol=20",
    )  # fmt: skip
    _, out, _ = run("balances")
    assert out == "alice 5.00\nbob -3.00\ncarol -2.00\n"


def test_percent_not_adding_up_is_reported_and_nothing_is_saved(run):
    code, _, err = run(
        "add", "--paid-by", "alice", "--amount", "10", "--description", "x",
        "--percent", "alice=50", "--percent", "bob=40",
    )  # fmt: skip
    assert code == 2
    assert "100" in err
    assert run("list")[1] == ""


def test_with_and_percent_cannot_be_combined(run):
    with pytest.raises(SystemExit):
        run("add", "--paid-by", "alice", "--amount", "10", "--description", "x", "--with", "bob", "--percent", "bob=100")
